steps.code:
# Now, let's match the songs in old_songs (which contains dicts with title and artist) to the song_ids in the playlists.
# We'll build a set of song_ids_to_archive that match any song in old_songs by title and artist.

song_ids_to_archive = set()
for song_id, details in song_id_to_details.items():
    for old_song in old_songs:
        # Match title (case-insensitive, strip whitespace) and artist (any match in artists list)
        if (
            details["title"].strip().lower() == old_song["title"].strip().lower() and
            any(artist.strip().lower() == old_song["artist"].strip().lower() for artist in details["artists"])
        ):
            song_ids_to_archive.add(int(song_id))
            break

print(song_ids_to_archive)

