steps.code:
# Let's attempt to map each song in old_songs to a Spotify song_id by searching Spotify for each title and artist.
# We'll use the spotify.search_songs API for each song, using a query like "title artist".
# We'll collect the best match for each song (if any) and build old_song_to_spotify_id.

old_song_to_spotify_id = []
for song in old_songs:
    query = f'{song["title"]} {song["artist"]}'
    results = apis.spotify.search_songs(
        access_token=spotify_access_token,
        query=query,
        page_limit=5
    )
    # Try to find the best match by title and artist
    best_match = None
    for result in results:
        # Check if both title and artist are in the result (case-insensitive)
        if song["title"].lower() in result["title"].lower() and all(
            artist.strip().lower() in result["artist"].lower()
            for artist in song["artist"].split(",")
        ):
            best_match = result
            break
    if best_match:
        old_song_to_spotify_id.append({
            "title": song["title"],
            "artist": song["artist"],
            "song_id": best_match["song_id"]
        })
    else:
        old_song_to_spotify_id.append({
            "title": song["title"],
            "artist": song["artist"],
            "song_id": None
        })

print(old_song_to_spotify_id)

