steps.code:
# Let's build a mapping from song_id to a string of "title by artist" for matching.
# We'll also build a reverse mapping from "title by artist" to song_id for easy lookup.
# Then, we'll identify which song_ids correspond to the songs_to_archive list.

def song_key(song):
    # Use the first artist for matching, as the archive list seems to use "title by artist"
    artist = song["artists"][0]["name"] if song["artists"] else ""
    return f"{song['title']} by {artist}"

song_id_to_key = {}
key_to_song_id = {}

for song in all_library_songs:
    key = song_key(song)
    song_id_to_key[song["song_id"]] = key
    key_to_song_id[key] = song["song_id"]

# Now, get the song_ids for songs_to_archive that exist in the library
archive_song_ids = []
for song_title in songs_to_archive:
    song_id = key_to_song_id.get(song_title)
    if song_id is not None:
        archive_song_ids.append(song_id)

print(archive_song_ids)  # These are the song_ids to remove from playlists and add to "Old Songs"

