# Only playlist_id 162 ("Vocal Virtuosity: A Cappella Excellence") contains the archived song.
# Next, let's check if a playlist named "Old Songs" already exists. If not, we'll create it.

old_songs_playlist = None
for playlist in all_playlists:
    if playlist["title"] == "Old Songs":
        old_songs_playlist = playlist
        break

if old_songs_playlist:
    old_songs_playlist_id = old_songs_playlist["playlist_id"]
else:
    old_songs_playlist_id = None

print(old_songs_playlist_id)  # None if it doesn't exist yet.

# To map the song titles from the archive list to Spotify song IDs, I need to look up each song in unique_song_ids,
# fetch its details using show_song, and match the title to the archive list.
# Let's fetch the details for all unique_song_ids and build a mapping from title to song_id.

# We'll do this in batches to avoid too many API calls at once.
archive_titles_set = set([title.strip().lower() for title in songs_to_archive])
title_to_song_id = {}

for song_id in unique_song_ids:
    song_details = apis.spotify.show_song(song_id=song_id)
    if "title" in song_details:
        song_title = song_details["title"].strip().lower()
        if song_title in archive_titles_set:
            title_to_song_id[song_title] = song_id

print(title_to_song_id)  # This will show which archive titles matched to which song IDs.

