# Next, let's check if a playlist named "Archived Playlist Songs" already exists.
# If not, we will create it. If it exists, we'll get its playlist_id.

archived_playlist_name = "Archived Playlist Songs"
archived_playlist_id = None
for playlist in playlists:
    if playlist["name"].strip().lower() == archived_playlist_name.lower():
        archived_playlist_id = playlist["playlist_id"]
        break

if archived_playlist_id is not None:
    print({"archived_playlist_id": archived_playlist_id})
else:
    # Let's see the API for creating a playlist in Spotify to proceed.
    print(apis.api_docs.show_api_descriptions(app_name="spotify"))

# The playlist name is under the "title" key, not "name". Let's fix the check and search for the "Archived Playlist Songs" playlist by its title.

archived_playlist_name = "Archived Playlist Songs"
archived_playlist_id = None
for playlist in playlists:
    if playlist["title"].strip().lower() == archived_playlist_name.lower():
        archived_playlist_id = playlist["playlist_id"]
        break

if archived_playlist_id is not None:
    print({"archived_playlist_id": archived_playlist_id})
else:
    # Let's see the API for creating a playlist in Spotify to proceed.
    print(apis.api_docs.show_api_descriptions(app_name="spotify"))

