steps.code:
# The note format is different than expected: each line is like "Song Title BY Artist(s) RELEASED_AT <info>".
# Let's update the lines for "Astral Serenity BY Orion Steele" and "Between Reality and Reverie BY Aria Sterling" to include their release months.
# "Astral Serenity" by Orion Steele: 12/2019
# "Between Reality and Reverie" by Aria Sterling: 03/2020

def update_release_months_note(note_content):
    lines = note_content.splitlines()
    updated_lines = []
    for line in lines:
        if "Astral Serenity BY Orion Steele" in line:
            updated_lines.append("- Astral Serenity BY Orion Steele RELEASED_AT 12/2019")
        elif "Between Reality and Reverie BY Aria Sterling" in line:
            updated_lines.append("- Between Reality and Reverie BY Aria Sterling RELEASED_AT 03/2020")
        else:
            updated_lines.append(line)
    return "\n".join(updated_lines)

final_note_content = update_release_months_note(updated_note_content)
print(final_note_content)

